function bm_out(array $x,int $s=200):never{http_response_code($s);echo json_encode($x,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function bm_default():array{return ['revision'=>0,'brokerageMaster'=>['productRates'=>[],'whtRates'=>[]]];}
function bm_read():array{tt_ensure_data_dir();$h=@fopen(BM_FILE,'rb');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('store');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} return tt_accounts_source_decode($raw,bm_default());}
function bm_can_view(array $u):bool{return tt_user_can_open_module($u,'Accounts')||tt_user_can_open_module($u,'Directors')||($u['role']??'')==='Super Admin';}
function bm_can_write(array $u,?string $action=null):bool {
    if(($u['role']??'')==='Super Admin')return true;
    foreach(['Directors','Accounts'] as $module){
        $p=$u['permissions'][$module]??null;
        if($p==='all')return true;
        // Retain the old flat, module-wide write grant. Granular matrices must
        // name Brokerage explicitly; rights on Reports never authorize rates.
        if(is_array($p)&&array_is_list($p)&&array_intersect($action===null?['Create','Edit']:[$action],$p))return true;
        foreach($action===null?['Create','Edit']:[$action] as $required)if(tt_user_can_module_action($u,$module,'brokerage',$required))return true;
    }
    return false;
}
